class NativeQueryBaseTrackedUnknownTest {
	private static final Value VALUE = SimpleValueFactory.getInstance().createIRI("urn:query-base:external");

	@ParameterizedTest(name = "trackedUnknown={0}")
	@ValueSource(booleans = { true, false })
	void emptyQueryBaseDoesNotChangeAuthorityAtALaterRealEntry(boolean trackedUnknown) {
		BindingSet original = new MapBindingSet();
		if (trackedUnknown) {
			original = BindingSetOrigin.with(original, BindingSetOrigin.of(EmptyBindingSet.getInstance()));
		}
		assertTrue(original.isEmpty());
		assertFalse(BindingSetOrigin.of(original).isRequest("external"));
		assertFalse(BindingSetOrigin.of(original).isLocal("external"));
		assertFalse(BindingSetOrigin.of(original).hasParameters());

		QueryBindingSet direct = new QueryBindingSet(original);
		direct.setBinding("external", VALUE);
		BindingSet directEntry = entry(direct);
		assertEquals(!trackedUnknown, BindingSetOrigin.of(directEntry).isRequest("external"),
				"the ordinary entry itself must distinguish tracked UNKNOWN from genuinely untracked input");

		try (NativeExecutionContext owner = new NativeExecutionContext(QueryExecutionPolicy.DEFAULT)) {
			owner.initializeQueryBase(original);
			assertTrue(owner.queryBase().isEmpty(), "the query base must not seed operand bindings");
			// Use the ordinary metadata-preserving constructor to isolate query-base storage from native-copy
			// transport.
			QueryBindingSet frame = new QueryBindingSet(owner.queryBase());
			frame.setBinding("external", VALUE);
			BindingSet actual = entry(frame);
			assertEquals(directEntry, actual, "value mappings are equal; only permitted entry authority differs");
			assertEquals(!trackedUnknown, BindingSetOrigin.of(actual).isRequest("external"),
					"storing an empty query base must not turn tracked UNKNOWN into new request authority");
			assertFalse(BindingSetOrigin.of(actual).isLocal("external"));
		}
	}

	private static BindingSet entry(BindingSet frame) {
		TripleSource triples = new TripleSource() {
			@Override
			public ValueFactory getValueFactory() {
				return SimpleValueFactory.getInstance();
			}

			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource s, IRI p, Value o,
					Resource... contexts) {
				return new EmptyIteration<>();
			}
		};
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(triples, (FederatedServiceResolver) null);
		try (var rows = strategy.precompile(new SingletonSet()).evaluate(frame)) {
			List<BindingSet> result = QueryResults.asList(rows);
			assertEquals(1, result.size());
			assertEquals(VALUE, result.get(0).getValue("external"));
			return result.get(0);
		}
	}
}
